/* Flip clock timer styles */
.fc-digit {
    width: 80px;
    height: 68px;
    perspective: 400px;
    font-variant-numeric: tabular-nums;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
}

/* Shared pseudo-element text style */
.fc-upper::after,
.fc-lower::after,
.fc-fold-top::after,
.fc-fold-bot::after {
    content: attr(data-value);
    position: absolute;
    left: 0;
    width: 100%;
    height: 68px;
    text-align: center;
    line-height: 68px;
    font-size: 36px;
    font-weight: 700;
    color: #fff;
}

/* --- Static top half (shows NEW value behind falling flap) --- */
.fc-upper {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 50%;
    overflow: hidden;
    background: #333;
    border-radius: 10px 10px 0 0;
}
.fc-upper::after {
    top: 0;
}

/* --- Static bottom half (shows OLD value, covered by unfolding flap) --- */
.fc-lower {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 50%;
    overflow: hidden;
    background: #2b2b2b;
    border-radius: 0 0 10px 10px;
}
.fc-lower::after {
    bottom: 0;
}

/* --- Center divider line (always visible above everything) --- */
.fc-divider {
    position: absolute;
    top: 50%;
    left: 0;
    width: 100%;
    height: 1px;
    background: #000;
    z-index: 20;
    transform: translateY(-1px);
    pointer-events: none;
}

/* --- Top fold: OLD value falls down (hinged at center) --- */
.fc-fold-top {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 50%;
    overflow: hidden;
    background: #333;
    border-radius: 10px 10px 0 0;
    transform-origin: center bottom;
    animation: fc-foldTop 0.3s cubic-bezier(0.37, 0.01, 0.94, 0.35) both;
    z-index: 10;
}
.fc-fold-top::after {
    top: 0;
}

/* --- Bottom fold: NEW value unfolds down (hinged at center) --- */
.fc-fold-bot {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 50%;
    overflow: hidden;
    background: #2b2b2b;
    border-radius: 0 0 10px 10px;
    transform-origin: center top;
    animation: fc-foldBot 0.6s cubic-bezier(0.15, 0.45, 0.28, 1) both;
    z-index: 10;
}
.fc-fold-bot::after {
    bottom: 0;
}

@keyframes fc-foldTop {
    0% {
        transform: rotateX(0deg);
    }
    100% {
        transform: rotateX(-90deg);
    }
}

@keyframes fc-foldBot {
    0%,
    50% {
        transform: rotateX(90deg);
    }
    100% {
        transform: rotateX(0deg);
    }
}

