    html[data-theme="dark"] .pd-theme .\!skeletonLoader {
        background-color: rgb(var(--pai-sunken, var(--pd-sunken))) !important;
        background-image: linear-gradient(110deg, rgb(var(--pai-sunken, var(--pd-sunken))) 8%, rgb(var(--pai-line, var(--pd-line))) 18%, rgb(var(--pai-sunken, var(--pd-sunken))) 33%) !important;
    }
    /* The generating-slide placeholder's sweep (SlideGeneratingSkeleton, redesign host): the same white band as the
       legacy inline one on light, a faint ink band on the dark surface (plain CSS + fallbacks: compiles under every app). */
    .slide-gen-sweep {
