/* ds Marquee (common/uicomponents/ds/Marquee.jsx): a caption that does not fit slides left by its overflow
   (--ds-marquee-shift, set inline), rests, and slides back; the class is only applied when the text overflows.
   Plain CSS so it compiles under every brand config and is never purged. */
.ds-marquee > span {
    animation-name: ds-marquee;
    animation-timing-function: linear;
    animation-iteration-count: infinite;
    will-change: transform;
}
@keyframes ds-marquee {
    0%,
    10% {
        transform: translateX(0);
    }
    50%,
    60% {
        transform: translateX(var(--ds-marquee-shift, 0));
    }
    100% {
        transform: translateX(0);
    }
}
@media (prefers-reduced-motion: reduce) {
    .ds-marquee {
        text-overflow: ellipsis;
    }
    .ds-marquee > span {
        animation: none;
    }
}

